+}
+</script>
+<script>
+  function showFallback(msg) {
+    var app = document.getElementById('app');
+    if (app) app.hidden = true;
+    var fb = document.getElementById('fallback');
+    if (!fb) return;
+    fb.hidden = false;
+    var p = document.getElementById('fallbackMsg');
+    if (msg && p) p.textContent = msg;
+  }
+  setTimeout(function () {
+    if (!window.__hvacBooted) showFallback('This exhibit needs WebGL, which did not start.');
+  }, 20000);
+</script>
+</head>
+<body>
+<div id="fallback" hidden>
+  <div>
+    <h1>Grok 4.7</h1>
+    <p id="fallbackMsg">This exhibit needs WebGL, which is unavailable here.</p>
+  </div>
+</div>
+<div id="app">
+  <div id="stage"></div>
+  <div id="vignette"></div>
+  <header class="panel"><h1>Grok 4.7</h1></header>
+  <section id="readout" class="panel" aria-live="polite">
+    <p id="modeLine">Split system · Cooling</p>
+    <p id="dayLine">Warm day</p>
+    <div class="temps">
+      <div><span>Indoor</span><strong id="inTemp">27.4°C</strong></div>
+      <div><span>Outdoor</span><strong id="outTemp">31.0°C</strong></div>
+    </div>
+    <p id="absorbLine">Absorbing heat at the indoor coil</p>
+    <p id="releaseLine">Releasing heat at the outdoor coil</p>
+    <p id="airLine">Room air and outdoor air stay separate</p>
+  </section>
+  <section id="lesson" class="panel">
+    <p id="stepNum">1 / 10</p>
+    <p id="lessonText"></p>
+  </section>
+  <ul id="legend" class="panel">
+    <li><i style="background:#f0c27a"></i>Room air</li>
+    <li><i style="background:#8eb0d0"></i>Outdoor air</li>
+    <li><i style="background:#3ee0c5"></i>Refrigerant</li>
+    <li><i style="background:#ff6a2c"></i>Heat</li>
+    <li><i style="background:#c5dcec"></i>Condensate</li>
+  </ul>
+  <p id="hint">Drag to orbit · Scroll or pinch to zoom</p>
+  <div id="controls" class="panel">
+    <div class="seg" role="group" aria-label="System">
+      <button type="button" data-system="split" aria-pressed="true">Split</button>
+      <button type="button" data-system="mono" aria-pressed="false">Monoblock</button>
+    </div>
+    <div class="seg" role="group" aria-label="Mode">
+      <button type="button" data-mode="cool" aria-pressed="true">Cooling</button>
+      <button type="button" data-mode="heat" aria-pressed="false">Heating</button>
+    </div>
+    <button type="button" id="playBtn" aria-pressed="true">Pause</button>
+    <button type="button" id="resetBtn">Reset view</button>
+    <button type="button" id="replayBtn">Replay guide</button>
+  </div>
+</div>
+<script type="module">
+import * as THREE from 'three';
+import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
+import { CSS2DRenderer, CSS2DObject } from 'three/addons/renderers/CSS2DRenderer.js';
+
+const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
+const GUIDE_STEP = 6.4;
+const GUIDE = [
+  { system: 'split', mode: 'cool', text: 'Air conditioning moves heat. It does not create cold.' },
+  { system: 'split', mode: 'cool', text: 'Refrigerant stays in a sealed loop. Room air and outdoor air never mix.' },
+  { system: 'split', mode: 'cool', text: 'A split system joins an indoor unit and an outdoor unit with two refrigerant lines.' },
+  { system: 'split', mode: 'cool', text: 'Cooling: the indoor coil absorbs room heat. Moisture condenses there as water, not refrigerant.' },
+  { system: 'split', mode: 'cool', text: 'The outdoor coil releases that heat. The compressor raises pressure; the expansion device drops it.' },
+  { system: 'split', mode: 'heat', text: 'Heating: the reversing valve swaps the coils. Condensation follows the cold coil, now outdoors.' },
+  { system: 'split', mode: 'heat', text: 'The outdoor coil absorbs heat from outside air. Fans keep their direction; the refrigerant reverses.' },
+  { system: 'mono', mode: 'cool', text: 'A monoblock puts the whole loop in one indoor cabinet.' },
+  { system: 'mono', mode: 'cool', text: 'Outdoor air enters and leaves through separate ducts. It never mixes with room air.' },
+  { system: 'mono', mode: 'heat', text: 'Same physics, different housing: one coil absorbs heat and the other releases it.' }
+];
+
+const HOME_POS = new THREE.Vector3(1.22, 1.36, 2.52);
+const HOME_TGT = new THREE.Vector3(-0.02, 1.06, -0.58);
+const state = { system: 'split', mode: 'cool' };
+const temps = { indoor: 27.4, outdoor: 31.0, indoorTarget: 22.6, outdoorTarget: 33.0 };
+let playing = !reducedMotion;
+let guidePlaying = !reducedMotion;
+let guideIndex = 0;
+let guideAcc = 0;
+let flowDir = 1;
+
+const streams = [];
+const arrows = [];
+const fans = [];
+const thermals = [];
+const leds = [];
+const dynamicLabels = [];
+const dropRooms = [];
+const dropOuts = [];
+const flowMats = [];
+const shuttles = [];
+const _p = new THREE.Vector3();
+const _t = new THREE.Vector3();
+const _y = new THREE.Vector3(0, 1, 0);
+
+const $ = (id) => document.getElementById(id);
+const modeLine = $('modeLine');
+const dayLine = $('dayLine');
+const inTemp = $('inTemp');
+const outTemp = $('outTemp');
+const absorbLine = $('absorbLine');
+const releaseLine = $('releaseLine');
+const lessonText = $('lessonText');
+const stepNum = $('stepNum');
+const playBtn = $('playBtn');
+
+function showBootError(err) {
+  console.error(err);
+  showFallback('This exhibit needs WebGL, which did not start.');
+}
+
+try {
+  boot();
+} catch (err) {
+  showBootError(err);
+}
+
+function boot() {
+  const stage = $('stage');
+  let renderer;
+  try {
+    renderer = new THREE.WebGLRenderer({
+      antialias: true,
+      alpha: false,
+      powerPreference: 'high-performance',
+      failIfMajorPerformanceCaveat: false
+    });
+  } catch (err) {
+    showBootError(err);
+    return;
+  }
+  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
+  renderer.setSize(window.innerWidth, window.innerHeight);
+  renderer.outputColorSpace = THREE.SRGBColorSpace;
+  renderer.toneMapping = THREE.ACESFilmicToneMapping;
+  renderer.toneMappingExposure = 1.05;
+  renderer.shadowMap.enabled = true;
+  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
+  renderer.setClearColor(0x9bb0c2, 1);
+  stage.appendChild(renderer.domElement);
+  renderer.domElement.addEventListener('webglcontextlost', (e) => {
+    e.preventDefault();
+    showFallback('WebGL stopped. Reload the page to restart the exhibit.');
+  });
+
+  const labelRenderer = new CSS2DRenderer();
+  labelRenderer.setSize(window.innerWidth, window.innerHeight);
+  labelRenderer.domElement.style.position = 'absolute';
+  labelRenderer.domElement.style.inset = '0';
+  labelRenderer.domElement.style.pointerEvents = 'none';
+  labelRenderer.domElement.style.zIndex = '2';
+  stage.appendChild(labelRenderer.domElement);
+
+  const scene = new THREE.Scene();
+  const camera = new THREE.PerspectiveCamera(40, 1, 0.06, 80);
+  const controls = new OrbitControls(camera, renderer.domElement);
+  controls.enableDamping = !reducedMotion;
+  controls.dampingFactor = 0.08;
+  controls.minDistance = 1.35;
+  controls.maxDistance = 7.2;
+  controls.maxPolarAngle = Math.PI * 0.49;
+  controls.minPolarAngle = 0.18;
+  controls.target.copy(HOME_TGT);
+
+  const pmrem = new THREE.PMREMGenerator(renderer);
+  const env = new THREE.Scene();
+  env.background = new THREE.Color(0xb9c8d6);
+  const envSky = new THREE.Mesh(new THREE.SphereGeometry(8, 16, 12), new THREE.MeshBasicMaterial({ color: 0xd5e2ee, side: THREE.BackSide }));
+  const envGround = new THREE.Mesh(new THREE.CircleGeometry(7, 18), new THREE.MeshBasicMaterial({ color: 0x6a6156 }));
+  envGround.rotation.x = -Math.PI / 2;
+  const envSun = new THREE.Mesh(new THREE.CircleGeometry(1.4, 16), new THREE.MeshBasicMaterial({ color: 0xfff3d4 }));
+  envSun.position.set(3, 5, 2);
+  env.add(envSky, envGround, envSun);
+  scene.environment = pmrem.fromScene(env, 0.04).texture;
+  scene.environmentIntensity = 0.82;
+  pmrem.dispose();
+
+  const hemi = new THREE.HemisphereLight(0xd5e2ef, 0x6a5b4c, 1.15);
+  scene.add(hemi);
+  const sun = new THREE.DirectionalLight(0xfff3e2, 4.4);
+  sun.position.set(5.2, 7.4, 3.2);
+  sun.castShadow = true;
+  const shadowSize = window.innerWidth < 800 ? 1024 : 2048;
+  sun.shadow.mapSize.set(shadowSize, shadowSize);
+  sun.shadow.camera.left = -4;
+  sun.shadow.camera.right = 4;
+  sun.shadow.camera.top = 4;
+  sun.shadow.camera.bottom = -4;
+  sun.shadow.camera.near = 0.5;
+  sun.shadow.camera.far = 20;
+  sun.shadow.bias = -0.00035;
+  sun.shadow.normalBias = 0.03;
+  sun.target.position.set(0, 1, -0.6);
+  scene.add(sun, sun.target);
+  const fill = new THREE.DirectionalLight(0xc9d7ea, 1.15);
+  fill.position.set(-2.4, 2.6, 3.4);
+  scene.add(fill);
+  const lamp = new THREE.PointLight(0xffc291, 18, 6.5, 2);
+  lamp.position.set(-2.15, 2.05, -1.35);
+  scene.add(lamp);
+
+  const M = makeMaterials();
+  buildSky(scene);
+  buildArchitecture(scene, M);
+  const splitRoot = new THREE.Group();
+  const monoRoot = new THREE.Group();
+  scene.add(splitRoot, monoRoot);
+  const splitHeatC = new THREE.Group();
+  const splitHeatH = new THREE.Group();
+  const monoHeatC = new THREE.Group();
+  const monoHeatH = new THREE.Group();
+  splitRoot.add(splitHeatC, splitHeatH);
+  monoRoot.add(monoHeatC, monoHeatH);
+
+  buildSplit(splitRoot, splitHeatC, splitHeatH, M);
+  buildMono(monoRoot, monoHeatC, monoHeatH, M);
+
+  function frameCamera() {
+    const aspect = window.innerWidth / Math.max(1, window.innerHeight);
+    camera.fov = aspect < 0.85 ? 58 : 40;
+    camera.aspect = aspect;
+    camera.updateProjectionMatrix();
+  }
+  function applyHome() {
+    const aspect = window.innerWidth / Math.max(1, window.innerHeight);
+    const offset = HOME_POS.clone().sub(HOME_TGT);
+    if (aspect < 0.85) offset.multiplyScalar(1.3);
+    camera.position.copy(HOME_TGT).add(offset);
+    controls.target.copy(HOME_TGT);
+    controls.update();
+  }
+  function resize() {
+    frameCamera();
+    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
+    renderer.setSize(window.innerWidth, window.innerHeight);
+    labelRenderer.setSize(window.innerWidth, window.innerHeight);
+  }
+  resize();
+  applyHome();
+  window.addEventListener('resize', resize);
+
+  function syncScene() {
+    splitRoot.visible = state.system === 'split';
+    monoRoot.visible = state.system === 'mono';
+    splitHeatC.visible = state.mode === 'cool';
+    splitHeatH.visible = state.mode === 'heat';
+    monoHeatC.visible = state.mode === 'cool';
+    monoHeatH.visible = state.mode === 'heat';
+    flowDir = state.mode === 'cool' ? 1 : -1;
+    for (const mat of flowMats) mat.uniforms.uDir.value = flowDir;
+    const cool = state.mode === 'cool';
+    for (const item of thermals) paintThermal(item.mat, item.roomSide ? cool : !cool);
+    for (const item of leds) paintLed(item.mat, item.roomSide ? cool : !cool);
+    for (const g of dropRooms) g.visible = cool;
+    for (const g of dropOuts) g.visible = !cool;
+    for (const s of shuttles) s.mesh.position.x = cool ? s.cool : s.heat;
+    for (const L of dynamicLabels) {
+      if (L.role === 'roomCoil') L.em.textContent = cool ? 'Absorbs heat' : 'Releases heat';
+      if (L.role === 'outCoil') L.em.textContent = cool ? 'Releases heat' : 'Absorbs heat';
+      if (L.role === 'valve') L.em.textContent = cool ? 'Cooling path' : 'Heating path';
+      if (L.role === 'condRoom') L.obj.visible = cool;
+      if (L.role === 'condOut') L.obj.visible = !cool;
+    }
+    const split = state.system === 'split';
+    const room = split ? 'indoor coil' : 'room coil';
+    const out = split ? 'outdoor coil' : 'outdoor-air coil';
+    modeLine.textContent = (split ? 'Split system' : 'Monoblock') + ' · ' + (cool ? 'Cooling' : 'Heating');
+    dayLine.textContent = cool ? 'Warm day' : 'Cold day';
+    absorbLine.textContent = 'Absorbing heat at the ' + (cool ? room : out);
+    releaseLine.textContent = 'Releasing heat at the ' + (cool ? out : room);
+    inTemp.style.color = cool ? '#b7d4ff' : '#ffc39a';
+    outTemp.style.color = cool ? '#ffc39a' : '#b7d4ff';
+    document.querySelectorAll('[data-system]').forEach((b) => {
+      b.setAttribute('aria-pressed', b.dataset.system === state.system ? 'true' : 'false');
+    });
+    document.querySelectorAll('[data-mode]').forEach((b) => {
+      b.setAttribute('aria-pressed', b.dataset.mode === state.mode ? 'true' : 'false');
+    });
+    paintTemps();
+  }
+
+  function initTempsFor(mode) {
+    if (mode === 'cool') {
+      temps.indoor = 27.4;
+      temps.outdoor = 31.0;
+      temps.indoorTarget = 22.6;
+      temps.outdoorTarget = 33.0;
+    } else {
+      temps.indoor = 17.6;
+      temps.outdoor = 8.6;
+      temps.indoorTarget = 21.6;
+      temps.outdoorTarget = 5.8;
+    }
+    if (reducedMotion || !playing) {
+      temps.indoor = temps.indoorTarget;
+      temps.outdoor = temps.outdoorTarget;
+    }
+  }
+
+  function applyGuideStep(i, forceTemps) {
+    const step = GUIDE[i];
+    const modeChanged = state.mode !== step.mode;
+    state.system = step.system;
+    state.mode = step.mode;
+    if (modeChanged || forceTemps) initTempsFor(step.mode);
+    syncScene();
+    lessonText.textContent = step.text;
+    stepNum.textContent = (i + 1) + ' / ' + GUIDE.length;
+  }
+
+  function showLive() {
+    const split = state.system === 'split';
+    const cool = state.mode === 'cool';
+    const pack = split
+      ? 'Split system: indoor and outdoor coils share one sealed refrigerant loop.'
+      : 'Monoblock: the full loop is indoors. Outdoor air uses separate intake and exhaust ducts.';
+    const flow = cool
+      ? ' Cooling absorbs heat on the room side and releases it outdoors.'
+      : ' Heating absorbs heat outdoors and releases it into the room.';
+    const water = cool
+      ? ' Moisture condenses on the cold room coil.'
+      : ' The outdoor coil is cold now, so condensation moves outside.';
+    lessonText.textContent = pack + flow + water;
+    stepNum.textContent = 'Live';
+  }
+
+  function setPlaying(v) {
+    playing = v;
+    playBtn.textContent = v ? 'Pause' : 'Play';
+    playBtn.setAttribute('aria-pressed', v ? 'true' : 'false');
+  }
+
+  document.querySelectorAll('[data-system]').forEach((b) => {
+    b.addEventListener('click', () => {
+      guidePlaying = false;
+      if (state.system !== b.dataset.system) {
+        state.system = b.dataset.system;
+        syncScene();
+      }
+      showLive();
